export async function addMute(
  orgId: OrgId,
  userId: UserId,
  projectId: ProjectId,
): Promise<void> {
  getDb()
    .insert(projectMutes)
    .values({ orgId, userId, projectId })
    .onConflictDoNothing()
    .run();
}

export async function removeMute(
  orgId: OrgId,
  userId: UserId,
  projectId: ProjectId,
): Promise<void> {
  getDb()
    .delete(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.userId, userId),
        eq(projectMutes.projectId, projectId),
      ),
    )
    .run();
}

